/* קובץ נוצר אוטומטית ע"י scripts/build-pages.js - אין לערוך ידנית */
export const PAGES = {
  "admin.html": "<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>ניהול - מערכת הצבעות</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 100 100%27><text y=%2780%27 font-size=%2780%27>📊</text></svg>\">\n<style>\n  :root {\n    --surface: #101014; --surface-2: #1a1a21; --surface-3: #23232c;\n    --text-1: #fff; --text-2: #c3c2c9; --text-3: #8a8994;\n    --accent: #3987e5; --good: #34c26b; --bad: #e66767; --warn: #c98500;\n    --track: #26262e;\n  }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  body { font-family: 'Segoe UI', 'Heebo', Arial, sans-serif; background: var(--surface); color: var(--text-1); min-height: 100vh; padding: 20px; }\n  h1 { font-size: 1.4rem; margin-bottom: 14px; display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }\n  h1 a { color: var(--accent); font-size: .9rem; }\n  nav { display: flex; gap: 6px; margin-bottom: 18px; flex-wrap: wrap; }\n  nav button { background: var(--surface-2); border: none; color: var(--text-2); font: inherit; font-weight: 600; padding: 10px 20px; border-radius: 12px; cursor: pointer; }\n  nav button.active { background: var(--accent); color: #fff; }\n  .tab { display: none; }\n  .tab.active { display: block; }\n  .card { background: var(--surface-2); border-radius: 16px; padding: 18px; margin-bottom: 14px; }\n  button { font: inherit; font-weight: 600; cursor: pointer; background: var(--surface-3); color: var(--text-1); border: none; border-radius: 10px; padding: 8px 14px; }\n  button:hover { filter: brightness(1.2); }\n  button.primary { background: var(--accent); } button.good { background: var(--good); color: #06220f; }\n  button.bad { background: var(--bad); color: #2a0808; } button.warn { background: var(--warn); color: #221600; }\n  button.sm { font-size: .82rem; padding: 5px 10px; }\n  input, select, textarea { font: inherit; background: var(--surface); color: var(--text-1); border: 1px solid var(--track); border-radius: 10px; padding: 8px 12px; }\n  input:focus, select:focus, textarea:focus { outline: 2px solid var(--accent); }\n  label { font-size: .85rem; color: var(--text-3); display: block; margin-bottom: 3px; }\n  .field { display: flex; flex-direction: column; }\n  .row { display: flex; gap: 10px; flex-wrap: wrap; align-items: flex-end; margin-bottom: 10px; }\n  table { width: 100%; border-collapse: collapse; font-size: .92rem; }\n  th { text-align: start; color: var(--text-3); font-weight: 600; padding: 8px; border-bottom: 1px solid var(--track); }\n  td { padding: 8px; border-bottom: 1px solid var(--track); vertical-align: middle; }\n  .badge { border-radius: 8px; padding: 2px 10px; font-size: .8rem; font-weight: 700; }\n  .badge.active { background: color-mix(in srgb, var(--good) 25%, transparent); color: var(--good); }\n  .badge.draft { background: var(--surface-3); color: var(--text-3); }\n  .badge.closed { background: color-mix(in srgb, var(--bad) 22%, transparent); color: var(--bad); }\n  .opt-row { display: grid; grid-template-columns: 70px 1fr 1fr 90px 44px; gap: 8px; margin-bottom: 8px; align-items: center; }\n  #toast { position: fixed; bottom: 20px; right: 50%; transform: translateX(50%); background: var(--surface-3); border: 1px solid var(--track); border-radius: 12px; padding: 12px 22px; display: none; z-index: 99; font-weight: 600; }\n  #toast.err { border-color: var(--bad); color: var(--bad); }\n  dialog { background: var(--surface-2); color: var(--text-1); border: 1px solid var(--track); border-radius: 18px; padding: 24px; max-width: 720px; width: 92vw; max-height: 90vh; overflow: auto; }\n  dialog::backdrop { background: rgba(0,0,0,.6); }\n  .settings-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 12px; }\n  .login-box { max-width: 420px; margin: 12vh auto; text-align: center; display: flex; flex-direction: column; gap: 14px; }\n  .muted { color: var(--text-3); font-size: .85rem; }\n  .switch { display: flex; align-items: center; gap: 8px; cursor: pointer; font-size: .95rem; color: var(--text-2); }\n  .switch input { width: 20px; height: 20px; accent-color: var(--accent); }\n</style>\n</head>\n<body>\n\n<div id=\"login\" class=\"login-box\" style=\"display:none\">\n  <h1 style=\"justify-content:center\">⚙️ ממשק ניהול</h1>\n  <p class=\"muted\">הזינו את טוקן הניהול (ADMIN_TOKEN שהוגדר כסוד ב-Cloudflare)</p>\n  <input id=\"token-input\" type=\"password\" placeholder=\"טוקן ניהול\" style=\"text-align:center\">\n  <button class=\"primary\" onclick=\"saveToken()\">כניסה</button>\n</div>\n\n<div id=\"app\" style=\"display:none\">\n  <h1>\n    ⚙️ ממשק ניהול - מערכת הצבעות וטריוויה\n    <span style=\"flex:1\"></span>\n    <a href=\"control.html\">🎛️ שולחן שליטה</a>\n    <a href=\"display.html\" target=\"_blank\">🖥️ תצוגה</a>\n    <a href=\"judge.html\" target=\"_blank\">⚖️ שופטים</a>\n    <button class=\"sm\" onclick=\"logout()\">יציאה</button>\n  </h1>\n\n  <nav>\n    <button data-tab=\"questions\" class=\"active\" onclick=\"showTab('questions')\">📋 שאלות והצבעות</button>\n    <button data-tab=\"judges\" onclick=\"showTab('judges')\">⚖️ שופטים</button>\n    <button data-tab=\"participants\" onclick=\"showTab('participants')\">👥 משתתפים</button>\n    <button data-tab=\"settings\" onclick=\"showTab('settings')\">🔧 הגדרות וטקסטים</button>\n  </nav>\n\n  <!-- ============ שאלות ============ -->\n  <div class=\"tab active\" id=\"tab-questions\">\n    <div class=\"card\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <h2>שאלות</h2>\n        <button class=\"primary\" onclick=\"openQuestionDialog()\">+ שאלה חדשה</button>\n      </div>\n      <table id=\"questions-table\">\n        <thead><tr><th>כותרת</th><th>סוג</th><th>סטטוס</th><th>אפשרויות</th><th>שקלול שופטים</th><th>פעולות</th></tr></thead>\n        <tbody></tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- ============ שופטים ============ -->\n  <div class=\"tab\" id=\"tab-judges\">\n    <div class=\"card\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <h2>שופטים</h2>\n        <button class=\"primary\" onclick=\"openJudgeDialog()\">+ שופט חדש</button>\n      </div>\n      <p class=\"muted\">שופט מזוהה אוטומטית בטלפון לפי המספר ממנו התקשר, ובממשק הרשת לפי טלפון + קוד אישי. טווח האחוזים מגדיר אילו ציונים מותר לו לתת.</p>\n      <table id=\"judges-table\">\n        <thead><tr><th>שם</th><th>טלפון</th><th>טווח ציונים</th><th>הארכת זמן</th><th>ניהול טלפוני</th><th>פעיל</th><th>פעולות</th></tr></thead>\n        <tbody></tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- ============ משתתפים ============ -->\n  <div class=\"tab\" id=\"tab-participants\">\n    <div class=\"card\">\n      <h2>משתתפים - שינוי שמות בזמן אמת</h2>\n      <div class=\"row\">\n        <div class=\"field\"><label>טלפון</label><input id=\"np-phone\" placeholder=\"0501234567\"></div>\n        <div class=\"field\"><label>שם תצוגה</label><input id=\"np-name\" placeholder=\"שם\"></div>\n        <button class=\"primary\" onclick=\"addParticipant()\">הוסף / עדכן</button>\n      </div>\n      <table id=\"participants-table\">\n        <thead><tr><th>טלפון</th><th>שם תצוגה</th><th>נראה לאחרונה</th><th>פעולות</th></tr></thead>\n        <tbody></tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- ============ הגדרות ============ -->\n  <div class=\"tab\" id=\"tab-settings\">\n    <div class=\"card\">\n      <h2>טקסטים והתנהגות (משפיע מיידית על הטלפון והתצוגה)</h2>\n      <div class=\"settings-grid\" id=\"settings-grid\"></div>\n      <div class=\"row\" style=\"margin-top:14px\">\n        <button class=\"primary\" onclick=\"saveSettings()\">💾 שמור הכל</button>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h2>חיבור ימות המשיח</h2>\n      <p class=\"muted\" style=\"line-height:1.8\">\n        בשלוחה הרצויה במערכת ימות המשיח הגדירו קובץ ext.ini עם:<br>\n        <code style=\"background:var(--surface);padding:2px 8px;border-radius:6px;direction:ltr;display:inline-block\">type=api</code><br>\n        <code style=\"background:var(--surface);padding:2px 8px;border-radius:6px;direction:ltr;display:inline-block\" id=\"api-link\">api_link=https://YOUR-WORKER.workers.dev/ivr</code><br>\n        מומלץ גם: <code style=\"background:var(--surface);padding:2px 8px;border-radius:6px;direction:ltr;display:inline-block\">api_hangup_send=no</code>\n      </p>\n    </div>\n  </div>\n</div>\n\n<!-- דיאלוג שאלה -->\n<dialog id=\"q-dialog\">\n  <h2 id=\"q-dialog-title\" style=\"margin-bottom:14px\">שאלה חדשה</h2>\n  <div class=\"row\">\n    <div class=\"field\" style=\"flex:2\"><label>כותרת (מוצגת במסך)</label><input id=\"q-title\"></div>\n    <div class=\"field\"><label>סוג</label>\n      <select id=\"q-kind\">\n        <option value=\"poll\">הצבעה</option>\n        <option value=\"trivia\">טריוויה</option>\n        <option value=\"survey\">סקר</option>\n      </select>\n    </div>\n  </div>\n  <div class=\"row\">\n    <div class=\"field\" style=\"flex:1\"><label>נוסח הקראה בטלפון (רשות - אם שונה מהכותרת)</label><input id=\"q-tts\"></div>\n  </div>\n  <div class=\"row\">\n    <div class=\"field\"><label>מגבלת זמן בשניות (ריק = ללא)</label><input id=\"q-seconds\" type=\"number\" min=\"5\"></div>\n    <div class=\"field\"><label>שקלול שופטים באחוזים (0 = קהל בלבד)</label><input id=\"q-jweight\" type=\"number\" min=\"0\" max=\"100\" value=\"0\"></div>\n    <div class=\"field\"><label>קבוצת סקר (לשאלות מרובות ברצף)</label><input id=\"q-group\" placeholder=\"רשות\"></div>\n    <div class=\"field\"><label>סדר</label><input id=\"q-order\" type=\"number\" value=\"0\" style=\"width:80px\"></div>\n  </div>\n  <div class=\"row\">\n    <label class=\"switch\"><input type=\"checkbox\" id=\"q-show-live\" checked> תוצאות חיות בתצוגה</label>\n    <label class=\"switch\"><input type=\"checkbox\" id=\"q-allow-change\"> לאפשר שינוי הצבעה</label>\n    <label class=\"switch\"><input type=\"checkbox\" id=\"q-announce-left\"> להקריא זמן שנותר בטלפון</label>\n  </div>\n  <h3 style=\"margin:12px 0 8px\">אפשרויות תשובה</h3>\n  <div class=\"opt-row muted\"><span>ספרה</span><span>שם לתצוגה</span><span>נוסח הקראה (רשות)</span><span>צבע</span><span></span></div>\n  <div id=\"q-options\"></div>\n  <div class=\"row\">\n    <button class=\"sm\" onclick=\"addOptionRow()\">+ אפשרות</button>\n    <div class=\"field\"><label>תשובה נכונה (טריוויה - ספרה)</label><input id=\"q-correct\" type=\"number\" min=\"0\" max=\"9\" style=\"width:90px\"></div>\n  </div>\n  <div class=\"row\" style=\"justify-content:flex-end;margin-top:10px\">\n    <button onclick=\"document.getElementById('q-dialog').close()\">ביטול</button>\n    <button class=\"primary\" onclick=\"saveQuestion()\">💾 שמירה</button>\n  </div>\n</dialog>\n\n<!-- דיאלוג שופט -->\n<dialog id=\"j-dialog\">\n  <h2 id=\"j-dialog-title\" style=\"margin-bottom:14px\">שופט חדש</h2>\n  <div class=\"row\">\n    <div class=\"field\"><label>שם</label><input id=\"j-name\"></div>\n    <div class=\"field\"><label>טלפון (לזיהוי אוטומטי)</label><input id=\"j-phone\" placeholder=\"0501234567\"></div>\n    <div class=\"field\"><label>קוד אישי לממשק הרשת</label><input id=\"j-pin\" placeholder=\"רשות\"></div>\n  </div>\n  <div class=\"row\">\n    <div class=\"field\"><label>אחוז מינימלי</label><input id=\"j-min\" type=\"number\" min=\"0\" max=\"100\" value=\"0\"></div>\n    <div class=\"field\"><label>אחוז מקסימלי</label><input id=\"j-max\" type=\"number\" min=\"0\" max=\"100\" value=\"100\"></div>\n  </div>\n  <div class=\"row\">\n    <label class=\"switch\"><input type=\"checkbox\" id=\"j-extend\" checked> רשאי להאריך זמן מהטלפון</label>\n    <label class=\"switch\"><input type=\"checkbox\" id=\"j-control\"> תפריט ניהול טלפוני (סגירה/שאלה הבאה)</label>\n    <label class=\"switch\"><input type=\"checkbox\" id=\"j-active\" checked> פעיל</label>\n  </div>\n  <div class=\"row\" style=\"justify-content:flex-end;margin-top:10px\">\n    <button onclick=\"document.getElementById('j-dialog').close()\">ביטול</button>\n    <button class=\"primary\" onclick=\"saveJudge()\">💾 שמירה</button>\n  </div>\n</dialog>\n\n<div id=\"toast\"></div>\n\n<script>\n'use strict';\nconst $ = (id) => document.getElementById(id);\nlet TOKEN = localStorage.getItem('ari-admin-token') || '';\nlet questions = [], judges = [], settings = {}, editingQ = null, editingJ = null;\n\nconst SETTING_FIELDS = [\n  ['system_name', 'שם המערכת', 'text'],\n  ['greeting_text', 'ברכת פתיחה בטלפון', 'text'],\n  ['no_active_text', 'הודעה כשאין הצבעה פעילה', 'text'],\n  ['closed_text', 'הודעת הצבעה שהסתיימה', 'text'],\n  ['vote_saved_text', 'אישור קליטת הצבעה', 'text'],\n  ['already_voted_text', 'הודעת \"כבר הצבעת\"', 'text'],\n  ['invalid_choice_text', 'הודעת בחירה שגויה', 'text'],\n  ['results_intro_text', 'פתיח הקראת תוצאות', 'text'],\n  ['goodbye_text', 'ברכת סיום', 'text'],\n  ['judge_menu_text', 'פתיח תפריט שופט', 'text'],\n  ['judge_score_prompt', 'בקשת ציון שופט', 'text'],\n  ['extend_prompt', 'בקשת שניות הארכה', 'text'],\n  ['ask_name_text', 'בקשת אמירת שם', 'text'],\n  ['say_results_on_phone', 'הקראת תוצאות למצביע בטלפון', 'bool'],\n  ['allow_vote_change', 'שינוי הצבעה (ברירת מחדל גלובלית)', 'bool'],\n  ['ask_name_enabled', 'לבקש שם בדיבור ממצביע חדש', 'bool'],\n  ['results_visible_on_display', 'תוצאות גלויות בדף הצפייה', 'bool'],\n  ['reveal_correct', 'חשיפת תשובה נכונה בתצוגה', 'bool'],\n  ['display_theme', 'ערכת נושא לתצוגה (dark/light)', 'text'],\n  ['display_message', 'כיתוב רץ בתחתית התצוגה', 'text'],\n];\n\nfunction saveToken() { TOKEN = $('token-input').value.trim(); localStorage.setItem('ari-admin-token', TOKEN); location.reload(); }\nfunction logout() { localStorage.removeItem('ari-admin-token'); location.reload(); }\nif (!TOKEN) $('login').style.display = 'flex'; else $('app').style.display = 'block';\n\nasync function api(path, method = 'GET', body) {\n  const res = await fetch('/api' + path, {\n    method,\n    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + TOKEN },\n    body: body ? JSON.stringify(body) : undefined,\n  });\n  const data = await res.json().catch(() => ({}));\n  if (res.status === 401) { toast('טוקן שגוי', true); logout(); throw new Error('401'); }\n  if (!res.ok) { toast(data.error || 'שגיאה', true); throw new Error(data.error); }\n  return data;\n}\nfunction toast(msg, isErr = false) {\n  const t = $('toast'); t.textContent = msg; t.className = isErr ? 'err' : '';\n  t.style.display = 'block'; clearTimeout(t._h); t._h = setTimeout(() => t.style.display = 'none', 2600);\n}\nconst escapeHtml = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n\nfunction showTab(name) {\n  document.querySelectorAll('nav button').forEach((b) => b.classList.toggle('active', b.dataset.tab === name));\n  document.querySelectorAll('.tab').forEach((t) => t.classList.toggle('active', t.id === 'tab-' + name));\n}\n\n/* ============ שאלות ============ */\nasync function loadQuestions() {\n  ({ questions } = await api('/admin/questions'));\n  const tbody = $('questions-table').querySelector('tbody');\n  tbody.innerHTML = questions.map((q) => `\n    <tr>\n      <td><b>${escapeHtml(q.title)}</b>${q.survey_group ? `<div class=\"muted\">קבוצה: ${escapeHtml(q.survey_group)}</div>` : ''}</td>\n      <td>${{ poll: 'הצבעה', trivia: 'טריוויה', survey: 'סקר' }[q.kind] || q.kind}</td>\n      <td><span class=\"badge ${q.status}\">${{ active: 'פעילה', draft: 'טיוטה', closed: 'סגורה', archived: 'ארכיון' }[q.status]}</span></td>\n      <td>${(q.options || []).map((o) => `${o.digit}:${escapeHtml(o.label)}`).join(' · ')}</td>\n      <td>${q.judges_weight}%</td>\n      <td style=\"white-space:nowrap\">\n        ${q.status !== 'active'\n          ? `<button class=\"sm good\" onclick=\"activateQ('${q.id}')\">▶ הפעל</button>`\n          : `<button class=\"sm bad\" onclick=\"closeQ('${q.id}')\">⏹ סגור</button>`}\n        <button class=\"sm\" onclick=\"openQuestionDialog('${q.id}')\">✏️</button>\n        <button class=\"sm\" onclick=\"resetVotes('${q.id}')\">🗑 אפס הצבעות</button>\n        <button class=\"sm\" onclick=\"exportCsv('${q.id}')\">⬇ CSV</button>\n        <button class=\"sm\" onclick=\"simulate('${q.id}')\">🧪 הדמיה</button>\n        <button class=\"sm bad\" onclick=\"deleteQ('${q.id}')\">✕</button>\n      </td>\n    </tr>`).join('');\n}\nasync function activateQ(id) { await api(`/admin/questions/${id}/activate`, 'POST', {}); toast('השאלה הופעלה'); loadQuestions(); }\nasync function closeQ(id) { await api(`/admin/questions/${id}/close`, 'POST', {}); toast('נסגרה'); loadQuestions(); }\nasync function deleteQ(id) { if (!confirm('למחוק את השאלה וכל הצבעותיה?')) return; await api(`/admin/questions/${id}`, 'DELETE'); toast('נמחקה'); loadQuestions(); }\nasync function resetVotes(id) { if (!confirm('לאפס את כל ההצבעות וציוני השופטים לשאלה זו?')) return; await api(`/admin/questions/${id}/reset-votes`, 'POST', {}); toast('אופס'); }\nfunction exportCsv(id) {\n  fetch(`/api/admin/export/${id}`, { headers: { Authorization: 'Bearer ' + TOKEN } })\n    .then((r) => r.blob()).then((b) => {\n      const a = document.createElement('a');\n      a.href = URL.createObjectURL(b); a.download = `votes-${id}.csv`; a.click();\n    });\n}\nasync function simulate(id) {\n  const q = questions.find((x) => x.id === id);\n  const digits = (q.options || []).map((o) => o.digit);\n  if (!digits.length) return toast('אין אפשרויות', true);\n  for (let i = 0; i < 5; i++) {\n    await api(`/admin/questions/${id}/simulate-vote`, 'POST', { option_digit: digits[Math.floor(Math.random() * digits.length)] });\n  }\n  toast('נוספו 5 הצבעות הדמיה');\n}\n\nfunction openQuestionDialog(id) {\n  editingQ = id ? questions.find((q) => q.id === id) : null;\n  $('q-dialog-title').textContent = editingQ ? 'עריכת שאלה' : 'שאלה חדשה';\n  $('q-title').value = editingQ?.title || '';\n  $('q-tts').value = editingQ?.tts_text || '';\n  $('q-kind').value = editingQ?.kind || 'poll';\n  $('q-seconds').value = editingQ?.seconds_to_answer ?? '';\n  $('q-jweight').value = editingQ?.judges_weight ?? 0;\n  $('q-group').value = editingQ?.survey_group || '';\n  $('q-order').value = editingQ?.sort_order ?? 0;\n  $('q-correct').value = editingQ?.correct_digit ?? '';\n  $('q-show-live').checked = editingQ?.show_results_live ?? true;\n  $('q-allow-change').checked = editingQ?.allow_vote_change ?? false;\n  $('q-announce-left').checked = editingQ?.announce_time_left ?? false;\n  $('q-options').innerHTML = '';\n  const opts = editingQ?.options?.length ? editingQ.options : [{ digit: 1 }, { digit: 2 }];\n  opts.forEach((o) => addOptionRow(o));\n  $('q-dialog').showModal();\n}\nfunction addOptionRow(o = {}) {\n  const container = $('q-options');\n  const nextDigit = o.digit ?? (Math.max(0, ...[...container.querySelectorAll('.o-digit')].map((i) => Number(i.value) || 0)) + 1);\n  const div = document.createElement('div');\n  div.className = 'opt-row';\n  div.innerHTML = `\n    <input class=\"o-digit\" type=\"number\" min=\"0\" max=\"9\" value=\"${nextDigit}\">\n    <input class=\"o-label\" value=\"${escapeHtml(o.label || '')}\" placeholder=\"שם\">\n    <input class=\"o-tts\" value=\"${escapeHtml(o.tts_text || '')}\" placeholder=\"נוסח הקראה\">\n    <input class=\"o-color\" type=\"color\" value=\"${o.color || '#3987e5'}\" style=\"height:38px;padding:2px\">\n    <button class=\"sm bad\" onclick=\"this.parentElement.remove()\">✕</button>`;\n  container.appendChild(div);\n}\nasync function saveQuestion() {\n  const options = [...$('q-options').querySelectorAll('.opt-row')].map((row) => ({\n    digit: Number(row.querySelector('.o-digit').value),\n    label: row.querySelector('.o-label').value.trim(),\n    tts_text: row.querySelector('.o-tts').value.trim() || null,\n    color: row.querySelector('.o-color').value,\n  })).filter((o) => o.label);\n  const digits = options.map((o) => o.digit);\n  if (new Set(digits).size !== digits.length) return toast('ספרות כפולות באפשרויות', true);\n  const body = {\n    title: $('q-title').value.trim(),\n    tts_text: $('q-tts').value.trim() || null,\n    kind: $('q-kind').value,\n    seconds_to_answer: $('q-seconds').value ? Number($('q-seconds').value) : null,\n    judges_weight: Number($('q-jweight').value) || 0,\n    survey_group: $('q-group').value.trim() || null,\n    sort_order: Number($('q-order').value) || 0,\n    correct_digit: $('q-correct').value === '' ? null : Number($('q-correct').value),\n    show_results_live: $('q-show-live').checked,\n    allow_vote_change: $('q-allow-change').checked,\n    announce_time_left: $('q-announce-left').checked,\n    options,\n  };\n  if (!body.title) return toast('חסרה כותרת', true);\n  if (editingQ) await api(`/admin/questions/${editingQ.id}`, 'PATCH', body);\n  else await api('/admin/questions', 'POST', body);\n  $('q-dialog').close();\n  toast('נשמר');\n  loadQuestions();\n}\n\n/* ============ שופטים ============ */\nasync function loadJudges() {\n  ({ judges } = await api('/admin/judges'));\n  $('judges-table').querySelector('tbody').innerHTML = judges.map((j) => `\n    <tr>\n      <td><b>${escapeHtml(j.name)}</b></td>\n      <td dir=\"ltr\">${escapeHtml(j.phone)}</td>\n      <td>${j.min_percent}% - ${j.max_percent}%</td>\n      <td>${j.can_extend ? '✓' : '—'}</td>\n      <td>${j.can_control ? '✓' : '—'}</td>\n      <td>${j.active ? '✓' : '✕'}</td>\n      <td style=\"white-space:nowrap\">\n        <button class=\"sm\" onclick=\"openJudgeDialog('${j.id}')\">✏️</button>\n        <button class=\"sm bad\" onclick=\"deleteJudge('${j.id}')\">✕</button>\n      </td>\n    </tr>`).join('');\n}\nfunction openJudgeDialog(id) {\n  editingJ = id ? judges.find((j) => j.id === id) : null;\n  $('j-dialog-title').textContent = editingJ ? 'עריכת שופט' : 'שופט חדש';\n  $('j-name').value = editingJ?.name || '';\n  $('j-phone').value = editingJ?.phone || '';\n  $('j-pin').value = editingJ?.pin || '';\n  $('j-min').value = editingJ?.min_percent ?? 0;\n  $('j-max').value = editingJ?.max_percent ?? 100;\n  $('j-extend').checked = editingJ?.can_extend ?? true;\n  $('j-control').checked = editingJ?.can_control ?? false;\n  $('j-active').checked = editingJ?.active ?? true;\n  $('j-dialog').showModal();\n}\nasync function saveJudge() {\n  const body = {\n    name: $('j-name').value.trim(),\n    phone: $('j-phone').value.trim(),\n    pin: $('j-pin').value.trim() || null,\n    min_percent: Number($('j-min').value) || 0,\n    max_percent: Number($('j-max').value) || 100,\n    can_extend: $('j-extend').checked,\n    can_control: $('j-control').checked,\n    active: $('j-active').checked,\n  };\n  if (!body.name || !body.phone) return toast('חסר שם או טלפון', true);\n  if (body.min_percent > body.max_percent) return toast('טווח אחוזים הפוך', true);\n  if (editingJ) await api(`/admin/judges/${editingJ.id}`, 'PATCH', body);\n  else await api('/admin/judges', 'POST', body);\n  $('j-dialog').close(); toast('נשמר'); loadJudges();\n}\nasync function deleteJudge(id) { if (!confirm('למחוק שופט?')) return; await api(`/admin/judges/${id}`, 'DELETE'); toast('נמחק'); loadJudges(); }\n\n/* ============ משתתפים ============ */\nasync function loadParticipants() {\n  const { participants } = await api('/admin/participants');\n  $('participants-table').querySelector('tbody').innerHTML = participants.map((p) => `\n    <tr>\n      <td dir=\"ltr\">${escapeHtml(p.phone)}</td>\n      <td><input value=\"${escapeHtml(p.display_name || '')}\" onchange=\"renameParticipant('${escapeHtml(p.phone)}', this.value)\"></td>\n      <td class=\"muted\">${p.last_seen ? new Date(p.last_seen).toLocaleString('he-IL') : '—'}</td>\n      <td><button class=\"sm bad\" onclick=\"deleteParticipant('${escapeHtml(p.phone)}')\">✕</button></td>\n    </tr>`).join('');\n}\nasync function addParticipant() {\n  const phone = $('np-phone').value.trim();\n  if (!phone) return toast('חסר טלפון', true);\n  await api('/admin/participants', 'POST', { phone, display_name: $('np-name').value.trim() });\n  $('np-phone').value = ''; $('np-name').value = '';\n  toast('נשמר'); loadParticipants();\n}\nasync function renameParticipant(phone, name) {\n  await api('/admin/participants', 'POST', { phone, display_name: name });\n  toast('שם עודכן בזמן אמת');\n}\nasync function deleteParticipant(phone) {\n  await api(`/admin/participants/${encodeURIComponent(phone)}`, 'DELETE');\n  loadParticipants();\n}\n\n/* ============ הגדרות ============ */\nasync function loadSettings() {\n  ({ settings } = await api('/admin/settings'));\n  $('settings-grid').innerHTML = SETTING_FIELDS.map(([key, label, type]) => type === 'bool'\n    ? `<label class=\"switch\"><input type=\"checkbox\" id=\"set-${key}\" ${settings[key] ? 'checked' : ''}> ${label}</label>`\n    : `<div class=\"field\"><label>${label}</label><input id=\"set-${key}\" value=\"${escapeHtml(settings[key] ?? '')}\"></div>`,\n  ).join('');\n  $('api-link').textContent = `api_link=${location.origin}/ivr`;\n}\nasync function saveSettings() {\n  const body = {};\n  for (const [key, , type] of SETTING_FIELDS) {\n    const el = $('set-' + key);\n    if (!el) continue;\n    body[key] = type === 'bool' ? el.checked : el.value;\n  }\n  await api('/admin/settings', 'POST', body);\n  toast('ההגדרות נשמרו והוחלו מיידית');\n}\n\n/* ============ אתחול ============ */\nif (TOKEN) {\n  loadQuestions(); loadJudges(); loadParticipants(); loadSettings();\n  setInterval(loadQuestions, 10000);\n}\n</script>\n</body>\n</html>\n",
  "control.html": "<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>שולחן שליטה - מערכת הצבעות</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 100 100%27><text y=%2780%27 font-size=%2780%27>📊</text></svg>\">\n<style>\n  :root {\n    --surface: #101014; --surface-2: #1a1a21; --surface-3: #23232c;\n    --text-1: #fff; --text-2: #c3c2c9; --text-3: #8a8994;\n    --accent: #3987e5; --good: #34c26b; --bad: #e66767; --warn: #c98500;\n    --track: #26262e;\n  }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  body { font-family: 'Segoe UI', 'Heebo', Arial, sans-serif; background: var(--surface); color: var(--text-1); min-height: 100vh; padding: 20px; }\n  h1 { font-size: 1.4rem; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }\n  h2 { font-size: 1.05rem; color: var(--text-2); margin-bottom: 10px; }\n  .status-chip { font-size: .85rem; border-radius: 20px; padding: 4px 14px; background: var(--surface-3); color: var(--text-3); }\n  .status-chip.on { background: color-mix(in srgb, var(--good) 22%, transparent); color: var(--good); }\n  .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 16px; margin-top: 18px; }\n  .card { background: var(--surface-2); border-radius: 16px; padding: 18px; }\n  button {\n    font-family: inherit; font-size: 1rem; font-weight: 600; cursor: pointer;\n    background: var(--surface-3); color: var(--text-1); border: none; border-radius: 10px; padding: 10px 16px;\n    transition: filter .15s;\n  }\n  button:hover { filter: brightness(1.2); }\n  button.primary { background: var(--accent); }\n  button.good { background: var(--good); color: #06220f; }\n  button.bad { background: var(--bad); color: #2a0808; }\n  button.warn { background: var(--warn); color: #221600; }\n  button:disabled { opacity: .4; cursor: not-allowed; }\n  .row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 10px; }\n  input, select {\n    font-family: inherit; font-size: 1rem; background: var(--surface); color: var(--text-1);\n    border: 1px solid var(--track); border-radius: 10px; padding: 9px 12px;\n  }\n  input:focus, select:focus { outline: 2px solid var(--accent); }\n  #question-now { font-size: 1.2rem; font-weight: 700; margin-bottom: 6px; }\n  #question-meta { color: var(--text-3); font-size: .9rem; margin-bottom: 12px; }\n  .mini-bars { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }\n  .mini-bar { display: grid; grid-template-columns: 110px 1fr 84px; gap: 10px; align-items: center; font-size: .92rem; }\n  .mini-track { background: var(--track); height: 14px; border-radius: 7px; overflow: hidden; }\n  .mini-fill { height: 100%; border-radius: 0 7px 7px 0; transition: width .6s; }\n  .num { font-variant-numeric: tabular-nums; color: var(--text-2); text-align: end; }\n  #toast {\n    position: fixed; bottom: 20px; right: 50%; transform: translateX(50%);\n    background: var(--surface-3); border-radius: 12px; padding: 12px 22px; display: none; z-index: 99;\n    border: 1px solid var(--track); font-weight: 600;\n  }\n  #toast.err { border-color: var(--bad); color: var(--bad); }\n  .rename-row { display: grid; grid-template-columns: 40px minmax(0, 1fr) auto auto; gap: 6px; margin-bottom: 8px; align-items: center; }\n  .rename-row input { min-width: 0; width: 100%; }\n  .rename-row button { padding: 8px 10px; font-size: .88rem; white-space: nowrap; }\n  .digit-chip { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; background: var(--surface-3); font-weight: 800; }\n  a { color: var(--accent); }\n  .login-box { max-width: 420px; margin: 12vh auto; text-align: center; display: flex; flex-direction: column; gap: 14px; }\n</style>\n</head>\n<body>\n\n<div id=\"login\" class=\"login-box\" style=\"display:none\">\n  <h1 style=\"justify-content:center\">🎛️ שולחן שליטה</h1>\n  <p style=\"color:var(--text-3)\">הזינו את טוקן הניהול (ADMIN_TOKEN שהוגדר ב-Cloudflare)</p>\n  <input id=\"token-input\" type=\"password\" placeholder=\"טוקן ניהול\" style=\"text-align:center\">\n  <button class=\"primary\" onclick=\"saveToken()\">כניסה</button>\n</div>\n\n<div id=\"app\" style=\"display:none\">\n  <h1>\n    🎛️ שולחן שליטה\n    <span class=\"status-chip\" id=\"display-status\">תצוגה: לא מחוברת</span>\n    <span class=\"status-chip\" id=\"server-status\">שרת: בודק...</span>\n    <span style=\"flex:1\"></span>\n    <button onclick=\"openDisplay()\" class=\"primary\">🖥️ פתח חלון תצוגה</button>\n    <a href=\"admin.html\" style=\"font-size:.9rem\">→ לממשק הניהול המלא</a>\n  </h1>\n\n  <div class=\"grid\">\n    <!-- מצב חי -->\n    <div class=\"card\">\n      <h2>📊 השאלה הפעילה</h2>\n      <div id=\"question-now\">אין שאלה פעילה</div>\n      <div id=\"question-meta\"></div>\n      <div class=\"row\">\n        <button class=\"good\" onclick=\"serverToggleResults(true)\">👁️ הצג תוצאות</button>\n        <button onclick=\"serverToggleResults(false)\">🙈 הסתר תוצאות</button>\n        <button class=\"warn\" onclick=\"revealCorrect()\">✓ חשוף תשובה נכונה</button>\n      </div>\n      <div class=\"row\">\n        <button class=\"bad\" onclick=\"closeQuestion()\">⏹️ סגור הצבעה</button>\n        <button class=\"primary\" onclick=\"nextQuestion()\">⏭️ שאלה הבאה בתור</button>\n      </div>\n      <div class=\"mini-bars\" id=\"mini-bars\"></div>\n    </div>\n\n    <!-- זמן -->\n    <div class=\"card\">\n      <h2>⏱️ הארכת זמן לכלל המשתמשים</h2>\n      <div class=\"row\">\n        <button onclick=\"extend(15)\">+15 שנ'</button>\n        <button onclick=\"extend(30)\">+30 שנ'</button>\n        <button onclick=\"extend(60)\">+60 שנ'</button>\n        <button onclick=\"extend(180)\">+3 דק'</button>\n      </div>\n      <div class=\"row\">\n        <input id=\"extend-custom\" type=\"number\" placeholder=\"שניות\" style=\"width:110px\">\n        <button onclick=\"extend(Number(document.getElementById('extend-custom').value))\">הארך</button>\n        <button class=\"bad\" onclick=\"extend(-15)\">-15 שנ' (קיצור)</button>\n      </div>\n      <div id=\"time-left\" style=\"font-size:2rem;font-weight:800;font-variant-numeric:tabular-nums;margin-top:8px\">--:--</div>\n    </div>\n\n    <!-- שמות בזמן אמת -->\n    <div class=\"card\">\n      <h2>✏️ שינוי שמות בזמן אמת</h2>\n      <div id=\"rename-list\" style=\"color:var(--text-3)\">אין אפשרויות פעילות</div>\n      <div class=\"row\" style=\"margin-top:8px\">\n        <button onclick=\"clearRenames()\">↺ בטל שינויים מקומיים בתצוגה</button>\n      </div>\n      <p style=\"color:var(--text-3);font-size:.82rem\">\"מקומי\" משנה רק את חלון התצוגה מיידית. \"שמור\" מעדכן את מסד הנתונים ואת הטלפון.</p>\n    </div>\n\n    <!-- אפקטים ותצוגה -->\n    <div class=\"card\">\n      <h2>✨ שליטה ישירה בחלון התצוגה</h2>\n      <div class=\"row\">\n        <button onclick=\"cmd({type:'confetti'})\">🎉 קונפטי</button>\n        <button onclick=\"cmd({type:'reveal_winner', dim:true})\">🏆 הכרזת מנצח</button>\n        <button onclick=\"cmd({type:'clear_reveal'})\">↺ בטל הכרזה</button>\n      </div>\n      <div class=\"row\">\n        <button onclick=\"cmd({type:'theme', value:'dark'})\">🌙 כהה</button>\n        <button onclick=\"cmd({type:'theme', value:'light'})\">☀️ בהיר</button>\n        <select id=\"zoom\" onchange=\"cmd({type:'zoom', value:this.value})\">\n          <option value=\"0.8\">זום 80%</option>\n          <option value=\"1\" selected>זום 100%</option>\n          <option value=\"1.2\">זום 120%</option>\n          <option value=\"1.5\">זום 150%</option>\n        </select>\n      </div>\n      <div class=\"row\">\n        <input id=\"overlay-text\" placeholder=\"הודעת ענק על המסך\" style=\"flex:1\">\n        <button onclick=\"cmd({type:'overlay', text:document.getElementById('overlay-text').value})\">הצג</button>\n        <button onclick=\"cmd({type:'overlay', text:''})\">נקה</button>\n      </div>\n      <div class=\"row\">\n        <input id=\"ticker-text\" placeholder=\"כיתוב רץ בתחתית (נשמר בשרת)\" style=\"flex:1\">\n        <button onclick=\"setTicker()\">שמור</button>\n        <button onclick=\"document.getElementById('ticker-text').value='';setTicker()\">נקה</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div id=\"toast\"></div>\n\n<script>\n'use strict';\nconst $ = (id) => document.getElementById(id);\nlet TOKEN = localStorage.getItem('ari-admin-token') || '';\nlet state = null;\nlet displayWin = null;\nlet displayAlive = 0;\n\n/* ---------- התחברות ---------- */\nfunction saveToken() {\n  TOKEN = $('token-input').value.trim();\n  localStorage.setItem('ari-admin-token', TOKEN);\n  location.reload();\n}\nif (!TOKEN) { $('login').style.display = 'flex'; }\nelse { $('app').style.display = 'block'; }\n\n/* ---------- API ---------- */\nasync function api(path, method = 'GET', body) {\n  const res = await fetch('/api' + path, {\n    method,\n    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + TOKEN },\n    body: body ? JSON.stringify(body) : undefined,\n  });\n  const data = await res.json().catch(() => ({}));\n  if (res.status === 401) {\n    localStorage.removeItem('ari-admin-token');\n    toast('טוקן שגוי - התחברו מחדש', true);\n    setTimeout(() => location.reload(), 1200);\n    throw new Error('401');\n  }\n  if (!res.ok) { toast(data.error || 'שגיאה', true); throw new Error(data.error); }\n  return data;\n}\n\nfunction toast(msg, isErr = false) {\n  const t = $('toast');\n  t.textContent = msg;\n  t.className = isErr ? 'err' : '';\n  t.style.display = 'block';\n  clearTimeout(t._h);\n  t._h = setTimeout(() => (t.style.display = 'none'), 2600);\n}\n\n/* ---------- תקשורת ישירה עם חלון התצוגה ---------- */\nconst bc = ('BroadcastChannel' in window) ? new BroadcastChannel('ari-trivia') : null;\nif (bc) {\n  bc.onmessage = (ev) => {\n    if (ev.data?.type === 'display_ready') { displayAlive = Date.now(); updateDisplayChip(); }\n  };\n}\nfunction updateDisplayChip() {\n  const connected = Date.now() - displayAlive < 4000;\n  const chip = $('display-status');\n  chip.textContent = connected ? 'תצוגה: מחוברת ✓' : 'תצוגה: לא מחוברת';\n  chip.classList.toggle('on', connected);\n}\nfunction cmd(c) {\n  bc?.postMessage(c);\n  // גיבוי דרך localStorage לדפדפנים בלי BroadcastChannel\n  localStorage.setItem('ari-trivia-cmd', JSON.stringify({ cmd: c, t: Date.now() }));\n  toast('נשלח לתצוגה');\n}\nfunction openDisplay() {\n  displayWin = window.open('display.html', 'ari-display', 'popup,width=1280,height=720');\n  setTimeout(() => bc?.postMessage({ type: 'ping' }), 800);\n}\nbc?.postMessage({ type: 'ping' });\nsetInterval(() => {\n  bc?.postMessage({ type: 'ping' });\n  updateDisplayChip();\n}, 2000);\n\n/* ---------- פעולות שרת ---------- */\nasync function serverToggleResults(visible) {\n  await api('/admin/settings', 'POST', { results_visible_on_display: visible });\n  cmd({ type: 'hide_results', value: null }); // ביטול דריסה מקומית\n  toast(visible ? 'תוצאות מוצגות' : 'תוצאות מוסתרות');\n}\nasync function revealCorrect() {\n  await api('/admin/settings', 'POST', { reveal_correct: true, results_visible_on_display: true });\n  cmd({ type: 'confetti' });\n  toast('התשובה הנכונה נחשפה');\n}\nasync function closeQuestion() {\n  if (!state?.question) return toast('אין שאלה פעילה', true);\n  await api(`/admin/questions/${state.question.id}/close`, 'POST', {});\n  toast('ההצבעה נסגרה');\n}\nasync function nextQuestion() {\n  // סגירת הנוכחית והפעלת הבאה בתור נעשות בצד השרת דרך פעולת activate של הבאה\n  const { questions } = await api('/admin/questions');\n  const next = questions.find((q) => q.status === 'draft');\n  if (!next) return toast('אין שאלה במצב טיוטה בתור', true);\n  await api(`/admin/questions/${next.id}/activate`, 'POST', {});\n  await api('/admin/settings', 'POST', { reveal_correct: false });\n  toast(`הופעלה: ${next.title}`);\n}\nasync function extend(seconds) {\n  if (!seconds) return;\n  if (!state?.question) return toast('אין שאלה פעילה', true);\n  const r = await api(`/admin/questions/${state.question.id}/extend`, 'POST', { seconds });\n  toast(`זמן עודכן ב-${seconds} שניות`);\n}\nasync function setTicker() {\n  await api('/admin/settings', 'POST', { display_message: $('ticker-text').value });\n  toast('כיתוב רץ עודכן');\n}\nfunction clearRenames() { cmd({ type: 'clear_renames' }); }\n\n/* ---------- שינוי שמות ---------- */\nfunction renderRenames() {\n  const list = $('rename-list');\n  const opts = state?.question?.options || [];\n  if (!opts.length) { list.textContent = 'אין אפשרויות פעילות'; return; }\n  if (list.dataset.key === state.question.id) return; // לא לדרוס בזמן הקלדה\n  list.dataset.key = state.question.id;\n  list.innerHTML = opts.map((o) => `\n    <div class=\"rename-row\">\n      <span class=\"digit-chip\">${o.digit}</span>\n      <input value=\"${escapeHtml(o.label)}\" id=\"rn-${o.digit}\">\n      <button onclick=\"cmd({type:'rename', digit:${o.digit}, name:document.getElementById('rn-${o.digit}').value})\">מקומי</button>\n      <button class=\"primary\" onclick=\"saveRename(${o.digit})\">שמור</button>\n    </div>`).join('');\n}\nasync function saveRename(digit) {\n  const name = $('rn-' + digit).value.trim();\n  if (!name || !state?.question) return;\n  const { questions } = await api('/admin/questions');\n  const q = questions.find((x) => x.id === state.question.id);\n  if (!q) return;\n  const options = q.options.map((o) => Number(o.digit) === digit ? { ...o, label: name } : o);\n  await api(`/admin/questions/${q.id}`, 'PATCH', { options });\n  cmd({ type: 'rename', digit, name });\n  toast('השם עודכן בכל המערכת');\n}\nconst escapeHtml = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n\n/* ---------- רענון מצב ---------- */\nasync function refresh() {\n  try {\n    const res = await fetch('/api/public/state', { cache: 'no-store' });\n    state = await res.json();\n    $('server-status').textContent = 'שרת: מחובר ✓';\n    $('server-status').classList.add('on');\n  } catch {\n    $('server-status').textContent = 'שרת: שגיאה';\n    $('server-status').classList.remove('on');\n    return;\n  }\n  const q = state.question;\n  $('question-now').textContent = q ? q.title : 'אין שאלה פעילה';\n  $('question-meta').textContent = q\n    ? `סטטוס: ${q.status === 'active' ? 'פתוחה' : 'סגורה'} | סוג: ${q.kind} | שקלול שופטים: ${q.judges_weight}%`\n    : '';\n\n  const bars = $('mini-bars');\n  const opts = state.results?.options || [];\n  bars.innerHTML = opts.map((o) => `\n    <div class=\"mini-bar\">\n      <span>${escapeHtml(o.label)}</span>\n      <div class=\"mini-track\"><div class=\"mini-fill\" style=\"width:${o.final_pct ?? 0}%;background:${o.color || 'var(--accent)'}\"></div></div>\n      <span class=\"num\">${o.final_pct === null ? 'מוסתר' : (o.final_pct + '% (' + o.votes + ')')}</span>\n    </div>`).join('');\n\n  const left = q?.seconds_left;\n  $('time-left').textContent = left === null || left === undefined\n    ? (q ? 'ללא הגבלה' : '--:--')\n    : `${String(Math.floor(left / 60)).padStart(2, '0')}:${String(left % 60).padStart(2, '0')}`;\n\n  renderRenames();\n}\nif (TOKEN) { refresh(); setInterval(refresh, 1500); }\n</script>\n</body>\n</html>\n",
  "display.html": "<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>תצוגה חיה - מערכת הצבעות</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 100 100%27><text y=%2780%27 font-size=%2780%27>📊</text></svg>\">\n<style>\n  :root {\n    --surface: #101014;\n    --surface-2: #1a1a21;\n    --text-1: #ffffff;\n    --text-2: #c3c2c9;\n    --text-3: #8a8994;\n    --accent: #3987e5;\n    --good: #34c26b;\n    --track: #26262e;\n    --s1: #3987e5; --s2: #199e70; --s3: #c98500; --s4: #008300;\n    --s5: #9085e9; --s6: #e66767; --s7: #d55181; --s8: #d95926;\n  }\n  [data-theme=\"light\"] {\n    --surface: #fcfcfb;\n    --surface-2: #f1f1ee;\n    --text-1: #0b0b0b;\n    --text-2: #52514e;\n    --text-3: #83827c;\n    --track: #e6e6e1;\n    --s1: #2a78d6; --s2: #1baf7a; --s3: #eda100; --s4: #008300;\n    --s5: #4a3aa7; --s6: #e34948; --s7: #e87ba4; --s8: #eb6834;\n  }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { height: 100%; }\n  body {\n    font-family: 'Segoe UI', 'Heebo', Arial, sans-serif;\n    background: var(--surface);\n    color: var(--text-1);\n    overflow: hidden;\n    transition: background .4s, color .4s;\n  }\n  #stage {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    padding: 3vh 4vw;\n    transform-origin: top center;\n  }\n\n  header { display: flex; justify-content: space-between; align-items: center; gap: 16px; }\n  #system-name { font-size: 1.4rem; color: var(--text-3); font-weight: 500; letter-spacing: .5px; }\n  #timer {\n    font-size: 2.2rem; font-weight: 700; font-variant-numeric: tabular-nums;\n    background: var(--surface-2); border-radius: 14px; padding: 6px 22px; min-width: 130px; text-align: center;\n  }\n  #timer.warn { color: #e66767; animation: pulse 1s infinite; }\n  @keyframes pulse { 50% { opacity: .55; } }\n  #timer.hidden, .hidden { display: none !important; }\n\n  #question {\n    font-size: clamp(2rem, 4.6vw, 4rem);\n    font-weight: 800; text-align: center; line-height: 1.25;\n    margin: 3.5vh 0 1.5vh;\n    text-wrap: balance;\n    display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;\n  }\n  /* כשיש הרבה אפשרויות - כותרת קומפקטית שלא גולשת על העמודות */\n  #stage.dense #question { font-size: clamp(1.4rem, 3vw, 2.6rem); margin: 1.5vh 0 1vh; -webkit-line-clamp: 2; }\n  #stage.dense #status-line { font-size: 1rem; }\n  #status-line { text-align: center; color: var(--text-3); font-size: 1.25rem; min-height: 1.8rem; }\n  #status-line .live-dot {\n    display: inline-block; width: 12px; height: 12px; border-radius: 50%;\n    background: #e34948; margin-inline-start: 8px; animation: pulse 1.4s infinite;\n  }\n\n  /* safe center: אם אין מקום - נצמד לראש ונגלל, בלי חיתוך וחפיפות */\n  #bars { flex: 1; display: flex; flex-direction: column; justify-content: safe center; gap: 2.8vh; min-height: 0; overflow-y: auto; padding: 4px 0; }\n  /* צפיפות אוטומטית כשיש הרבה אפשרויות */\n  #bars.dense { gap: 1.4vh; }\n  #bars.dense .bar-track { height: clamp(20px, 3.6vh, 40px); }\n  #bars.dense .bar-label { font-size: clamp(1rem, 1.8vw, 1.6rem); }\n  #bars.dense .bar-num { font-size: clamp(1.1rem, 2vw, 1.8rem); }\n  .bar-row { display: grid; grid-template-columns: minmax(140px, 18vw) 1fr auto; align-items: center; gap: 1.6vw; }\n  .bar-label { font-size: clamp(1.2rem, 2.4vw, 2.1rem); font-weight: 700; text-align: start; display: flex; align-items: center; gap: 8px 12px; min-width: 0; flex-wrap: wrap; }\n  .label-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1 1 3ch; min-width: 0; }\n  .digit-chip {\n    flex: none; width: 2.2em; height: 2.2em; font-size: .62em; border-radius: 12px;\n    display: grid; place-items: center; background: var(--surface-2); color: var(--text-2); font-weight: 800;\n    border: 2px solid var(--track);\n  }\n  .bar-track { background: var(--track); border-radius: 10px; height: clamp(28px, 5.4vh, 56px); overflow: hidden; position: relative; }\n  .bar-fill {\n    height: 100%; width: 0%;\n    border-radius: 0 10px 10px 0; /* קצה מעוגל בצד הצמיחה בלבד (RTL) */\n    transition: width .9s cubic-bezier(.2,.8,.2,1);\n    position: relative;\n  }\n  .bar-num { font-size: clamp(1.3rem, 2.6vw, 2.3rem); font-weight: 800; font-variant-numeric: tabular-nums; min-width: 5.2ch; text-align: end; }\n  .bar-votes { font-size: .55em; color: var(--text-3); font-weight: 500; display: block; }\n  .judge-chips { display: flex; gap: 6px; margin-top: 4px; flex-wrap: wrap; }\n  .judge-chip { font-size: .78rem; background: var(--surface-2); color: var(--text-2); border-radius: 8px; padding: 2px 8px; }\n\n  .bar-row.correct .bar-label::after { content: '✓ תשובה נכונה'; color: var(--good); font-size: .65em; font-weight: 800; flex: none; }\n  .bar-row.winner .bar-label::after { content: '🏆'; font-size: 1em; flex: none; }\n  .bar-row.winner .bar-fill { filter: brightness(1.15) drop-shadow(0 0 14px color-mix(in srgb, var(--accent) 70%, transparent)); }\n  .bar-row.winner { animation: winner-pop .7s cubic-bezier(.2,1.6,.4,1); }\n  @keyframes winner-pop { 30% { transform: scale(1.03); } }\n  .bar-row.leader .digit-chip { border-color: var(--accent); color: var(--accent); }\n  .bar-row.dimmed { opacity: .35; }\n  .bar-row { transition: opacity .4s; }\n  #question.swap { animation: q-swap .5s ease; }\n  @keyframes q-swap { from { opacity: 0; transform: translateY(14px); } }\n\n  /* מסכים צרים (טלפון/טאבלט): תווית מעל העמודה */\n  @media (max-width: 720px) {\n    .bar-row { grid-template-columns: 1fr auto; grid-template-areas: 'label num' 'track track'; row-gap: 6px; }\n    .bar-label { grid-area: label; }\n    .bar-track { grid-area: track; }\n    .bar-num { grid-area: num; }\n    #question { font-size: 1.6rem; }\n    #stage { padding: 2vh 4vw; }\n  }\n\n  footer { display: flex; justify-content: space-between; align-items: center; color: var(--text-3); font-size: 1.15rem; padding-top: 1.5vh; gap: 12px; flex-wrap: wrap; }\n  #fs-hint { font-size: .85rem; opacity: .7; }\n  #total-votes b { color: var(--text-1); font-size: 1.5rem; font-variant-numeric: tabular-nums; }\n\n  #ticker-wrap { position: fixed; bottom: 0; right: 0; left: 0; background: var(--accent); color: #fff; padding: 10px 0; display: none; }\n  #ticker { display: inline-block; white-space: nowrap; padding-inline-start: 100vw; animation: tick 18s linear infinite; font-size: 1.3rem; font-weight: 600; }\n  @keyframes tick { to { transform: translateX(100%); } } /* RTL: טקסט נכנס משמאל */\n\n  #overlay-msg {\n    position: fixed; inset: 0; display: none; place-items: center;\n    background: color-mix(in srgb, var(--surface) 82%, transparent);\n    backdrop-filter: blur(6px); z-index: 40;\n    font-size: clamp(2.4rem, 6vw, 5rem); font-weight: 900; text-align: center; padding: 4vw;\n  }\n  #waiting { display: grid; place-items: center; flex: 1; color: var(--text-3); font-size: clamp(1.8rem, 4vw, 3rem); font-weight: 600; text-align: center; }\n  #conn-lost { position: fixed; top: 12px; left: 12px; background: #e34948; color: #fff; border-radius: 10px; padding: 6px 14px; font-size: .95rem; display: none; z-index: 50; }\n  canvas#confetti { position: fixed; inset: 0; pointer-events: none; z-index: 60; }\n</style>\n</head>\n<body data-theme=\"dark\">\n<div id=\"conn-lost\">אין חיבור לשרת...</div>\n<div id=\"stage\">\n  <header>\n    <div id=\"system-name\">מערכת הצבעות</div>\n    <div id=\"timer\" class=\"hidden\">--:--</div>\n  </header>\n  <div id=\"question\"></div>\n  <div id=\"status-line\"></div>\n  <div id=\"bars\"></div>\n  <div id=\"waiting\">ממתינים לשאלה הבאה...</div>\n  <footer>\n    <div id=\"total-votes\">סה\"כ הצבעות: <b>0</b></div>\n    <div id=\"judges-weight-note\"></div>\n    <div id=\"fs-hint\">לחיצה כפולה או F למסך מלא</div>\n  </footer>\n</div>\n<div id=\"ticker-wrap\"><div id=\"ticker\"></div></div>\n<div id=\"overlay-msg\"></div>\n<canvas id=\"confetti\"></canvas>\n\n<script>\n'use strict';\n/* ============================================================\n   דף צפייה חיה.\n   מקור אמת: /api/public/state (משיכה כל שנייה).\n   שכבת שליטה מקומית: BroadcastChannel מדף השליטה (באותו מחשב),\n   לפעולות מיידיות - חשיפה, קונפטי, שינוי שם, ערכת נושא, זום.\n   ============================================================ */\n\nconst SERIES = ['--s1','--s2','--s3','--s4','--s5','--s6','--s7','--s8'];\nconst $ = (id) => document.getElementById(id);\n\nconst local = {           // דריסות מקומיות מדף השליטה\n  nameOverrides: {},      // digit -> שם\n  hideResults: null,      // null=לפי שרת, true/false=כפוי מקומית\n  revealWinner: false,\n  dimLosers: false,\n  zoom: 1,\n};\nlet lastState = null;\nlet lastFetchOk = Date.now();\nlet timerBase = null; // {closesAt, fetchedAt}\n\n/* ---------- תקשורת עם דף השליטה ---------- */\nconst bc = ('BroadcastChannel' in window) ? new BroadcastChannel('ari-trivia') : null;\nif (bc) {\n  bc.onmessage = (ev) => handleCommand(ev.data || {});\n  bc.postMessage({ type: 'display_ready' });\n}\n// גיבוי תקשורת: localStorage (עובד גם בלי BroadcastChannel)\nwindow.addEventListener('storage', (ev) => {\n  if (ev.key === 'ari-trivia-cmd' && ev.newValue) {\n    try { handleCommand(JSON.parse(ev.newValue).cmd); } catch {}\n  }\n});\n\nfunction handleCommand(cmd) {\n  switch (cmd.type) {\n    case 'ping': bc?.postMessage({ type: 'display_ready' }); break;\n    case 'theme': local.themeForced = true; document.body.dataset.theme = cmd.value; break;\n    case 'zoom':\n      local.zoom = Number(cmd.value) || 1;\n      $('stage').style.transform = `scale(${local.zoom})`;\n      break;\n    case 'rename': local.nameOverrides[cmd.digit] = cmd.name; render(); break;\n    case 'clear_renames': local.nameOverrides = {}; render(); break;\n    case 'hide_results': local.hideResults = cmd.value; render(); break;\n    case 'reveal_winner': local.revealWinner = true; local.dimLosers = !!cmd.dim; render(); confetti(); break;\n    case 'clear_reveal': local.revealWinner = false; local.dimLosers = false; render(); break;\n    case 'confetti': confetti(); break;\n    case 'overlay':\n      $('overlay-msg').textContent = cmd.text || '';\n      $('overlay-msg').style.display = cmd.text ? 'grid' : 'none';\n      break;\n    case 'refresh': fetchState(); break;\n  }\n}\n\n/* ---------- משיכת מצב מהשרת ---------- */\nasync function fetchState() {\n  try {\n    const res = await fetch('/api/public/state', { cache: 'no-store' });\n    if (!res.ok) throw new Error(res.status);\n    lastState = await res.json();\n    lastFetchOk = Date.now();\n    $('conn-lost').style.display = 'none';\n    if (lastState.question?.closes_at) {\n      timerBase = {\n        closesAt: new Date(lastState.question.closes_at).getTime(),\n        serverNow: new Date(lastState.server_time).getTime(),\n        fetchedAt: Date.now(),\n      };\n    } else timerBase = null;\n    render();\n  } catch {\n    if (Date.now() - lastFetchOk > 5000) $('conn-lost').style.display = 'block';\n  }\n}\n\n/* ---------- ציור ---------- */\nfunction render() {\n  if (!lastState) return;\n  const { settings, question, results } = lastState;\n\n  $('system-name').textContent = settings.system_name || '';\n  // ערכת נושא מהשרת אלא אם נכפתה מקומית מדף השליטה\n  if (!local.themeForced) document.body.dataset.theme = settings.display_theme || 'dark';\n\n  // כיתוב רץ\n  const ticker = settings.display_message || '';\n  $('ticker-wrap').style.display = ticker ? 'block' : 'none';\n  $('ticker').textContent = ticker;\n\n  if (!question) {\n    $('question').textContent = '';\n    $('status-line').textContent = '';\n    $('bars').innerHTML = '';\n    $('waiting').style.display = 'grid';\n    $('timer').classList.add('hidden');\n    $('total-votes').querySelector('b').textContent = '0';\n    return;\n  }\n  $('waiting').style.display = 'none';\n  if ($('question').textContent !== question.title) {\n    $('question').textContent = question.title;\n    $('question').classList.remove('swap');\n    void $('question').offsetWidth; // איפוס אנימציה\n    $('question').classList.add('swap');\n  }\n\n  const isOpen = question.status === 'active' && (question.seconds_left === null || question.seconds_left > 0) && !localTimerExpired();\n  $('status-line').innerHTML = isOpen\n    ? 'ההצבעה פתוחה - חייגו עכשיו <span class=\"live-dot\"></span>'\n    : 'ההצבעה סגורה';\n\n  const hide = local.hideResults !== null ? local.hideResults : (results?.hidden ?? false);\n  const opts = results?.options || (question.options || []).map((o) => ({ ...o, final_pct: null, votes: null }));\n  const maxPct = Math.max(...opts.map((o) => o.final_pct ?? 0), 0.001);\n  const winners = new Set(\n    opts.filter((o) => (o.final_pct ?? 0) >= maxPct - 0.001 && (o.final_pct ?? 0) > 0).map((o) => o.digit),\n  );\n\n  const bars = $('bars');\n  bars.classList.toggle('dense', opts.length > 5);\n  $('stage').classList.toggle('dense', opts.length > 5);\n  // בנייה מחדש רק אם מבנה האפשרויות השתנה - אחרת עדכון חלק לאנימציה\n  const key = question.id + ':' + opts.map((o) => o.digit).join(',');\n  if (bars.dataset.key !== key) {\n    bars.dataset.key = key;\n    bars.innerHTML = opts.map((o, i) => `\n      <div class=\"bar-row\" data-digit=\"${o.digit}\">\n        <div class=\"bar-label\"><span class=\"digit-chip\">${o.digit}</span><span class=\"label-text\"></span></div>\n        <div class=\"bar-track\"><div class=\"bar-fill\" style=\"background:${barColor(o, i)}\"></div></div>\n        <div class=\"bar-num\"><span class=\"pct\"></span><span class=\"bar-votes\"></span><div class=\"judge-chips\"></div></div>\n      </div>`).join('');\n  }\n\n  const maxVotes = Math.max(...opts.map((o) => o.votes ?? 0));\n  opts.forEach((o, i) => {\n    const row = bars.querySelector(`[data-digit=\"${o.digit}\"]`);\n    if (!row) return;\n    const label = local.nameOverrides[o.digit] ?? o.label;\n    const labelEl = row.querySelector('.label-text');\n    labelEl.textContent = label;\n    labelEl.title = label;\n    const pct = hide ? null : o.final_pct;\n    row.querySelector('.bar-fill').style.width = pct === null ? '0%' : Math.max(pct, 0.5) + '%';\n    animateNumber(row.querySelector('.pct'), pct);\n    row.querySelector('.bar-votes').textContent = hide || o.votes === null ? '' : `${o.votes} קולות`;\n    const chips = (o.judge_scores || []).map((s) => `<span class=\"judge-chip\">${s.judge}: ${s.score}</span>`).join('');\n    row.querySelector('.judge-chips').innerHTML = hide ? '' : chips;\n\n    row.classList.toggle('correct', !hide && question.correct_digit !== null && Number(question.correct_digit) === Number(o.digit));\n    row.classList.toggle('winner', local.revealWinner && !hide && winners.has(o.digit) && question.correct_digit === null);\n    row.classList.toggle('dimmed', local.dimLosers && !hide && !winners.has(o.digit));\n    row.classList.toggle('leader', !hide && maxVotes > 0 && (o.votes ?? 0) === maxVotes);\n  });\n\n  $('total-votes').querySelector('b').textContent = hide ? '···' : String(results?.total_votes ?? 0);\n  $('judges-weight-note').textContent = question.judges_weight > 0\n    ? `שקלול: ${question.judges_weight}% שופטים, ${100 - question.judges_weight}% קהל`\n    : '';\n}\n\nfunction barColor(opt, i) {\n  return opt.color || `var(${SERIES[i % SERIES.length]})`;\n}\n\n/* ---------- אנימציית ספירה חלקה למספרים ---------- */\nconst numAnims = new WeakMap();\nfunction animateNumber(el, target) {\n  if (target === null || target === undefined) { el.textContent = '?'; numAnims.delete(el); return; }\n  const from = numAnims.get(el) ?? 0;\n  if (Math.abs(from - target) < 0.05) { el.textContent = target.toFixed(1) + '%'; numAnims.set(el, target); return; }\n  numAnims.set(el, target);\n  const t0 = performance.now();\n  const dur = 700;\n  (function step(t) {\n    const p = Math.min(1, (t - t0) / dur);\n    const eased = 1 - Math.pow(1 - p, 3);\n    el.textContent = (from + (target - from) * eased).toFixed(1) + '%';\n    if (p < 1 && numAnims.get(el) === target) requestAnimationFrame(step);\n  })(t0);\n}\n\n/* ---------- מסך מלא (למקרן): לחיצה כפולה או מקש F ---------- */\nfunction toggleFullscreen() {\n  if (document.fullscreenElement) document.exitFullscreen();\n  else document.documentElement.requestFullscreen().catch(() => {});\n}\ndocument.addEventListener('dblclick', toggleFullscreen);\ndocument.addEventListener('keydown', (e) => {\n  if (e.key === 'f' || e.key === 'F' || e.key === 'כ') toggleFullscreen();\n});\n\n/* ---------- פקיעת טיימר מקומית (בלי לחכות לשרת) ---------- */\nfunction localTimerExpired() {\n  if (!timerBase) return false;\n  const serverNowEst = timerBase.serverNow + (Date.now() - timerBase.fetchedAt);\n  return timerBase.closesAt - serverNowEst <= 0;\n}\n\n/* ---------- טיימר חלק (מתוקן סטיית שעון מול השרת) ---------- */\nsetInterval(() => {\n  const t = $('timer');\n  if (!timerBase || !lastState?.question || lastState.question.status !== 'active') {\n    t.classList.add('hidden');\n    return;\n  }\n  const serverNowEst = timerBase.serverNow + (Date.now() - timerBase.fetchedAt);\n  const left = Math.max(0, Math.round((timerBase.closesAt - serverNowEst) / 1000));\n  t.classList.remove('hidden');\n  t.classList.toggle('warn', left <= 15 && left > 0);\n  t.textContent = `${String(Math.floor(left / 60)).padStart(2, '0')}:${String(left % 60).padStart(2, '0')}`;\n  // ברגע שהזמן פוקע - עדכון הסטטוס מיידית, בלי להמתין לשרת\n  if (left === 0 && $('status-line').querySelector('.live-dot')) render();\n}, 250);\n\n/* ---------- קונפטי ---------- */\nfunction confetti() {\n  const canvas = $('confetti');\n  const ctx = canvas.getContext('2d');\n  canvas.width = innerWidth; canvas.height = innerHeight;\n  const colors = SERIES.map((v) => getComputedStyle(document.body).getPropertyValue(v).trim());\n  const parts = Array.from({ length: 180 }, () => ({\n    x: Math.random() * canvas.width, y: -20 - Math.random() * canvas.height * .5,\n    vy: 2 + Math.random() * 4, vx: -2 + Math.random() * 4,\n    size: 6 + Math.random() * 8, color: colors[Math.floor(Math.random() * colors.length)],\n    rot: Math.random() * Math.PI, vr: -.1 + Math.random() * .2,\n  }));\n  const t0 = Date.now();\n  (function frame() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    for (const p of parts) {\n      p.x += p.vx; p.y += p.vy; p.rot += p.vr;\n      ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot);\n      ctx.fillStyle = p.color; ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);\n      ctx.restore();\n    }\n    if (Date.now() - t0 < 4500) requestAnimationFrame(frame);\n    else ctx.clearRect(0, 0, canvas.width, canvas.height);\n  })();\n}\n\nfetchState();\nsetInterval(fetchState, 1000);\n</script>\n</body>\n</html>\n",
  "index.html": "<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>מערכת הצבעות וטריוויה טלפונית</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 100 100%27><text y=%2780%27 font-size=%2780%27>📊</text></svg>\">\n<style>\n  :root { --surface:#101014; --surface-2:#1a1a21; --text-1:#fff; --text-3:#8a8994; --accent:#3987e5; --track:#26262e; }\n  * { margin:0; padding:0; box-sizing:border-box; }\n  body { font-family:'Segoe UI','Heebo',Arial,sans-serif; background:var(--surface); color:var(--text-1); min-height:100vh; display:grid; place-items:center; padding:20px; }\n  .wrap { max-width: 760px; width: 100%; text-align: center; }\n  h1 { font-size: 2rem; margin-bottom: 8px; }\n  p { color: var(--text-3); margin-bottom: 30px; }\n  .links { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 14px; }\n  a.tile { background: var(--surface-2); border: 1px solid var(--track); border-radius: 18px; padding: 26px 18px; color: var(--text-1); text-decoration: none; transition: transform .15s, border-color .15s; }\n  a.tile:hover { transform: translateY(-3px); border-color: var(--accent); }\n  .emoji { font-size: 2.2rem; display: block; margin-bottom: 10px; }\n  .tile b { display: block; margin-bottom: 4px; font-size: 1.1rem; }\n  .tile span.desc { color: var(--text-3); font-size: .85rem; }\n  #status { margin-top: 26px; color: var(--text-3); font-size: .9rem; }\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>📞 מערכת הצבעות וטריוויה טלפונית</h1>\n  <p>ימות המשיח · Cloudflare Workers · Supabase — הצבעות חיות, שופטים, סקרים ותצוגה בזמן אמת</p>\n  <div class=\"links\">\n    <a class=\"tile\" href=\"admin.html\"><span class=\"emoji\">⚙️</span><b>ממשק ניהול</b><span class=\"desc\">שאלות, שופטים, משתתפים והגדרות</span></a>\n    <a class=\"tile\" href=\"control.html\"><span class=\"emoji\">🎛️</span><b>שולחן שליטה</b><span class=\"desc\">שליטה חיה + פתיחת חלון התצוגה</span></a>\n    <a class=\"tile\" href=\"display.html\"><span class=\"emoji\">🖥️</span><b>תצוגה חיה</b><span class=\"desc\">מסך תוצאות באחוזים לקהל</span></a>\n    <a class=\"tile\" href=\"judge.html\"><span class=\"emoji\">⚖️</span><b>עמדת שופט</b><span class=\"desc\">מתן ציונים בטווח אישי</span></a>\n  </div>\n  <div id=\"status\">בודק חיבור לשרת...</div>\n</div>\n<script>\nfetch('/api/public/state').then(r => r.json()).then(s => {\n  document.getElementById('status').textContent = s.question\n    ? `✓ מחובר · שאלה פעילה: \"${s.question.title}\"`\n    : '✓ מחובר · אין שאלה פעילה כרגע';\n}).catch(() => document.getElementById('status').textContent = '✕ אין חיבור ל-API - בדקו הגדרות סודות ב-Cloudflare');\n</script>\n</body>\n</html>\n",
  "judge.html": "<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>עמדת שופט - מערכת הצבעות</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 100 100%27><text y=%2780%27 font-size=%2780%27>📊</text></svg>\">\n<style>\n  :root {\n    --surface: #101014; --surface-2: #1a1a21; --surface-3: #23232c;\n    --text-1: #fff; --text-2: #c3c2c9; --text-3: #8a8994;\n    --accent: #3987e5; --good: #34c26b; --bad: #e66767; --track: #26262e;\n  }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  body { font-family: 'Segoe UI', 'Heebo', Arial, sans-serif; background: var(--surface); color: var(--text-1); min-height: 100vh; padding: 20px; max-width: 640px; margin: 0 auto; }\n  h1 { font-size: 1.4rem; margin-bottom: 6px; }\n  .muted { color: var(--text-3); font-size: .9rem; }\n  .card { background: var(--surface-2); border-radius: 16px; padding: 20px; margin-top: 16px; }\n  input, button { font: inherit; border-radius: 10px; padding: 12px 14px; border: none; }\n  input { background: var(--surface); color: var(--text-1); border: 1px solid var(--track); width: 100%; margin-bottom: 10px; }\n  input:focus { outline: 2px solid var(--accent); }\n  button { background: var(--accent); color: #fff; font-weight: 700; cursor: pointer; width: 100%; }\n  button.secondary { background: var(--surface-3); }\n  button:disabled { opacity: .4; }\n  .range-badge { display: inline-block; background: color-mix(in srgb, var(--accent) 25%, transparent); color: var(--accent); border-radius: 20px; padding: 4px 16px; font-weight: 700; margin-top: 6px; }\n  .opt-card { background: var(--surface-3); border-radius: 14px; padding: 16px; margin-bottom: 14px; }\n  .opt-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; font-weight: 700; font-size: 1.1rem; }\n  .score-val { font-size: 1.6rem; font-variant-numeric: tabular-nums; color: var(--accent); font-weight: 800; }\n  input[type=range] { width: 100%; accent-color: var(--accent); height: 34px; margin: 0 0 10px; padding: 0; border: none; background: transparent; }\n  .saved-note { color: var(--good); font-size: .85rem; min-height: 1.2em; }\n  #toast { position: fixed; bottom: 20px; right: 50%; transform: translateX(50%); background: var(--surface-3); border: 1px solid var(--track); border-radius: 12px; padding: 12px 22px; display: none; z-index: 99; font-weight: 600; }\n  #toast.err { border-color: var(--bad); color: var(--bad); }\n</style>\n</head>\n<body>\n<h1>⚖️ עמדת שופט</h1>\n<div class=\"muted\">מתן ציונים בטווח האישי שהוגדר לך מראש</div>\n\n<div class=\"card\" id=\"login-card\">\n  <label class=\"muted\">מספר הטלפון שלך (כפי שהוגדר במערכת)</label>\n  <input id=\"phone\" placeholder=\"0501234567\" inputmode=\"tel\">\n  <label class=\"muted\">קוד אישי (אם הוגדר)</label>\n  <input id=\"pin\" type=\"password\" placeholder=\"קוד\">\n  <button onclick=\"login()\">כניסה</button>\n</div>\n\n<div id=\"panel\" style=\"display:none\">\n  <div class=\"card\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center\">\n      <div>\n        <b id=\"judge-name\"></b>\n        <div class=\"range-badge\" id=\"judge-range\"></div>\n      </div>\n      <button class=\"secondary\" style=\"width:auto\" onclick=\"logout()\">יציאה</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2 id=\"q-title\" style=\"margin-bottom:4px\">אין שאלה פעילה</h2>\n    <div class=\"muted\" id=\"q-meta\"></div>\n    <div id=\"options\" style=\"margin-top:14px\"></div>\n  </div>\n\n  <div class=\"card\" id=\"extend-card\" style=\"display:none\">\n    <h3 style=\"margin-bottom:10px\">⏱️ הארכת זמן לכלל המשתמשים</h3>\n    <div style=\"display:flex;gap:8px\">\n      <button class=\"secondary\" onclick=\"extend(30)\">+30 שנ'</button>\n      <button class=\"secondary\" onclick=\"extend(60)\">+60 שנ'</button>\n      <button class=\"secondary\" onclick=\"extend(120)\">+2 דק'</button>\n    </div>\n  </div>\n</div>\n\n<div id=\"toast\"></div>\n\n<script>\n'use strict';\nconst $ = (id) => document.getElementById(id);\nlet judge = null, question = null, myScores = {}, dirtyDigits = new Set();\n\nconst savedAuth = JSON.parse(localStorage.getItem('ari-judge-auth') || 'null');\nif (savedAuth) { $('phone').value = savedAuth.phone; $('pin').value = savedAuth.pin || ''; login(); }\n\nfunction toast(msg, isErr = false) {\n  const t = $('toast'); t.textContent = msg; t.className = isErr ? 'err' : '';\n  t.style.display = 'block'; clearTimeout(t._h); t._h = setTimeout(() => t.style.display = 'none', 2600);\n}\n\nfunction authHeaders() {\n  return {\n    'Content-Type': 'application/json',\n    'X-Judge-Phone': $('phone').value.trim(),\n    'X-Judge-Pin': $('pin').value.trim(),\n  };\n}\nasync function api(path, method = 'GET', body) {\n  const res = await fetch('/api' + path, { method, headers: authHeaders(), body: body ? JSON.stringify(body) : undefined });\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw new Error(data.error || 'שגיאה');\n  return data;\n}\n\nasync function login() {\n  try {\n    const data = await api('/judge/login', 'POST', {});\n    judge = data.judge;\n    localStorage.setItem('ari-judge-auth', JSON.stringify({ phone: $('phone').value.trim(), pin: $('pin').value.trim() }));\n    $('login-card').style.display = 'none';\n    $('panel').style.display = 'block';\n    $('judge-name').textContent = 'שלום, ' + judge.name;\n    $('judge-range').textContent = `הטווח שלך: ${judge.min_percent}% - ${judge.max_percent}%`;\n    $('extend-card').style.display = judge.can_extend ? 'block' : 'none';\n    refresh();\n    setInterval(refresh, 2500);\n  } catch (e) {\n    toast(e.message, true);\n  }\n}\nfunction logout() { localStorage.removeItem('ari-judge-auth'); location.reload(); }\n\nasync function refresh() {\n  let data;\n  try { data = await api('/judge/state'); } catch { return; }\n  question = data.question;\n  myScores = Object.fromEntries((data.my_scores || []).map((s) => [s.option_digit, Number(s.score)]));\n\n  if (!question) {\n    $('q-title').textContent = 'אין שאלה פעילה כרגע';\n    $('q-meta').textContent = 'העמוד יתעדכן אוטומטית כשתיפתח שאלה';\n    $('options').innerHTML = '';\n    $('options').dataset.key = '';\n    return;\n  }\n  $('q-title').textContent = question.title;\n  const left = question.seconds_left;\n  $('q-meta').textContent =\n    `משקל השופטים בתוצאה: ${question.judges_weight}%` +\n    (left !== null && left !== undefined ? ` | נותרו ${Math.floor(left / 60)}:${String(left % 60).padStart(2, '0')} להצבעה` : '');\n\n  const container = $('options');\n  if (container.dataset.key !== question.id) {\n    container.dataset.key = question.id;\n    dirtyDigits.clear();\n    container.innerHTML = question.options.map((o) => `\n      <div class=\"opt-card\" data-digit=\"${o.digit}\">\n        <div class=\"opt-head\">\n          <span>${o.digit}. ${escapeHtml(o.label)}</span>\n          <span class=\"score-val\" id=\"sv-${o.digit}\">—</span>\n        </div>\n        <input type=\"range\" id=\"sl-${o.digit}\" min=\"${judge.min_percent}\" max=\"${judge.max_percent}\"\n               value=\"${myScores[o.digit] ?? Math.round((judge.min_percent + judge.max_percent) / 2)}\"\n               oninput=\"onSlide(${o.digit}, this.value)\">\n        <button onclick=\"submitScore(${o.digit})\">שמור ציון</button>\n        <div class=\"saved-note\" id=\"sn-${o.digit}\"></div>\n      </div>`).join('');\n  }\n  // עדכון ציונים שמורים (בלי לדרוס סליידר שבעריכה)\n  for (const o of question.options) {\n    if (!dirtyDigits.has(o.digit) && myScores[o.digit] !== undefined) {\n      $('sl-' + o.digit).value = myScores[o.digit];\n      $('sv-' + o.digit).textContent = myScores[o.digit];\n      $('sn-' + o.digit).textContent = '✓ ציון שמור';\n    } else if (!dirtyDigits.has(o.digit)) {\n      $('sv-' + o.digit).textContent = $('sl-' + o.digit).value;\n    }\n  }\n}\nfunction onSlide(digit, val) {\n  dirtyDigits.add(digit);\n  $('sv-' + digit).textContent = val;\n  $('sn-' + digit).textContent = '';\n}\nasync function submitScore(digit) {\n  try {\n    const score = Number($('sl-' + digit).value);\n    await api('/judge/score', 'POST', { question_id: question.id, option_digit: digit, score });\n    dirtyDigits.delete(digit);\n    $('sn-' + digit).textContent = '✓ ציון שמור';\n    toast('הציון נשמר');\n  } catch (e) { toast(e.message, true); }\n}\nasync function extend(seconds) {\n  try { await api('/judge/extend', 'POST', { seconds }); toast(`הזמן הוארך ב-${seconds} שניות`); }\n  catch (e) { toast(e.message, true); }\n}\nconst escapeHtml = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n</script>\n</body>\n</html>\n",
};
